#!/usr/bin/env node
// D0-02d: tokens.json (approved Claude Design export) -> packages/ui/tokens/{tokens.css,tokens.ts}.
// Deterministic: same input bytes -> same output bytes (no dates, no environment, key order = JSON order).
//   node scripts/build-tokens.mjs           write the generated files
//   node scripts/build-tokens.mjs --check   write nothing; exit 1 if the checked-in files differ from the generated ones
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const pkgRoot = resolve(here, "..");
const repoRoot = resolve(pkgRoot, "../..");
export const SOURCE = join(repoRoot, "design/exports/design-system/tokens.json");
export const OUT_DIR = join(pkgRoot, "tokens");
const SOURCE_REL = relative(repoRoot, SOURCE);
const SCRIPT_REL = relative(repoRoot, fileURLToPath(import.meta.url));

// Group headings follow the export's own tokens.css (design brief section numbers).
const GROUPS = [
  ["color.bg.", "3.1 색: 면과 테두리"],
  ["color.border.subtle", "3.1 색: 면과 테두리"],
  ["color.border.default", "3.1 색: 면과 테두리"],
  ["color.text.", "3.2 색: 글자, 강조, 상태"],
  ["color.accent.", "3.2 색: 글자, 강조, 상태"],
  ["color.focus.", "3.2 색: 글자, 강조, 상태"],
  ["color.border.strong", "3.2 색: 글자, 강조, 상태"],
  ["color.status.", "3.2 색: 글자, 강조, 상태"],
  ["color.evidence.", "3.3 색: 증거 강도 스케일 (글자·테두리 / 바탕)"],
  ["color.badge.", "4절 값 배지"],
  ["font.", "3.4 타이포그래피"],
  ["type.", "3.4 타이포그래피"],
  ["space.", "3.5 간격, 크기, 모서리"],
  ["size.", "3.5 간격, 크기, 모서리"],
  ["radius.", "3.5 간격, 크기, 모서리"],
  ["elevation.", "3.6 높이"],
  ["motion.", "3.7 모션"],
];

// Global rules that the export's tokens.css carries after :root (brief 8절 focus ring, 3.7절 reduced motion).
// packages/ui/test/tokens.test.ts asserts this tail is byte-identical to the export's.
export const BASE_RULES = `/* 8절: 포커스 링 2 px + 간격 2 px */
:focus-visible {
  outline: 2px solid var(--kin-color-focus-ring);
  outline-offset: 2px;
}

/* 3.7절: 이동·크기 변화를 없애고 불투명도 전환만 남긴다 */
@media (prefers-reduced-motion: reduce) {
  * {
    transition-property: opacity !important;
    animation: none !important;
  }
}
`;

export const cssVarName = (name) => `--kin-${name.replaceAll(".", "-")}`;

function groupOf(name) {
  const hit = GROUPS.find(([prefix]) => name === prefix || name.startsWith(prefix));
  if (!hit) throw new Error(`token ${name} has no group; add it to GROUPS in build-tokens.mjs`);
  return hit[1];
}

export function generate(sourceText = readFileSync(SOURCE, "utf8")) {
  const parsed = JSON.parse(sourceText);
  const entries = Object.entries(parsed).filter(([k]) => k !== "$meta");
  if (entries.length === 0) throw new Error("tokens.json has no tokens");
  for (const [name, value] of entries) {
    if (typeof value !== "string" || value === "") throw new Error(`token ${name}: value must be a non-empty string`);
    if (!/^[a-z0-9]+(\.[a-z0-9]+)*$/.test(name)) throw new Error(`token name not allowed: ${name}`);
  }
  const sha = createHash("sha256").update(sourceText).digest("hex");
  const banner = [
    `Generated by ${SCRIPT_REL} from ${SOURCE_REL}`,
    `(sha256 ${sha}). Do not edit by hand: edit the approved export, then run \`pnpm --filter @kinetra/ui tokens\`.`,
    "Values are [제안] approved in #33; as value badge they are `기본값`.",
  ];

  let css = `/* ${banner.join("\n   ")} */\n:root {\n`;
  let current = null;
  for (const [name, value] of entries) {
    const group = groupOf(name);
    if (group !== current) {
      if (current !== null) css += "\n";
      css += `  /* ${group} */\n`;
      current = group;
    }
    css += `  ${cssVarName(name)}: ${value};\n`;
  }
  css += `}\n\n${BASE_RULES}`;

  const ts =
    `// ${banner.join("\n// ")}\n` +
    `export const tokens = {\n` +
    entries.map(([k, v]) => `  ${JSON.stringify(k)}: ${JSON.stringify(v)},\n`).join("") +
    `} as const;\n\n` +
    `export type TokenName = keyof typeof tokens;\n`;

  return { "tokens.css": css, "tokens.ts": ts };
}

export function main(argv = process.argv.slice(2)) {
  const check = argv.includes("--check");
  const files = generate();
  const stale = [];
  for (const [file, text] of Object.entries(files)) {
    const path = join(OUT_DIR, file);
    const onDisk = existsSync(path) ? readFileSync(path, "utf8") : null;
    if (check) {
      if (onDisk !== text) stale.push(relative(repoRoot, path));
    } else if (onDisk !== text) {
      mkdirSync(OUT_DIR, { recursive: true });
      writeFileSync(path, text);
      console.log(`wrote ${relative(repoRoot, path)}`);
    }
  }
  if (check) {
    if (stale.length) {
      console.error(`stale generated tokens (run: pnpm --filter @kinetra/ui tokens): ${stale.join(", ")}`);
      return 1;
    }
    console.log(`tokens up to date (${Object.keys(files).length} files)`);
  }
  return 0;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  process.exit(main());
}
